INSERT INTO familier (id, categorie, nom, nom_cle, effet_brut, description, ordre, origine, source_ref, remarque) VALUES ('ressources/familiers#familier:gros:amblypyge-noir', 'gros', 'Amblypyge noir', 'amblypyge-noir', NULL, 'L’amblypyge noir est un grand arachnide atteignant environ 1,15m, reconnaissable à ses longues pattes fines et à ses appendices sensoriels constamment en mouvement. Imprégné de l’énergie de la Corruption, il se déplace de façon étrangement silencieuse et semble sentir là où le brai est présent. Malgré son apparence repoussante, il développe une fidélité importante envers son propriétaire.', 1, 'craft', 'Ressources et Craft › Familiers › U12:AM16', NULL);
INSERT INTO familier (id, categorie, nom, nom_cle, effet_brut, description, ordre, origine, source_ref, remarque) VALUES ('ressources/familiers#familier:gros:araignee-argentee', 'gros', 'Araignée argentée', 'araignee-argentee', NULL, 'L’araignée argentée est un arachnide d’environ 1,15m dont la carapace métallique reflète faiblement la lumière. Liée à l’Arcane, elle produit naturellement de fins filaments chargés de chakra. Son comportement est méthodique et patient, observant son environnement avant d’agir avec précision.', 2, 'craft', 'Ressources et Craft › Familiers › U17:AM21', NULL);
INSERT INTO familier (id, categorie, nom, nom_cle, effet_brut, description, ordre, origine, source_ref, remarque) VALUES ('ressources/familiers#familier:gros:bouleguerre', 'gros', 'Bouleguerre', 'bouleguerre', NULL, 'Ce chien qui ressemble à un bouledogue français est un formidable compagnon et chasseur, lié à la magie du sang, il est doté d''un physique impressionnant pour un canidé (1m15 au garrot) et d''une force assez conséquente. Il possède 3 paires de pattes.', 3, 'craft', 'Ressources et Craft › Familiers › U22:AM26', NULL);
INSERT INTO familier (id, categorie, nom, nom_cle, effet_brut, description, ordre, origine, source_ref, remarque) VALUES ('ressources/familiers#familier:gros:faucon-vert', 'gros', 'Faucon vert', 'faucon-vert', NULL, 'Le faucon vert est un grand oiseau au plumage parcouru de nuances émeraude. Relié à la magie du Vent, il est réputé pour sa vitesse et son incroyable agilité aérienne. Son tempérament est fier et indépendant, bien qu’il développe une grande confiance envers ceux qu’il accepte.', 4, 'craft', 'Ressources et Craft › Familiers › U27:AM31', NULL);
INSERT INTO familier (id, categorie, nom, nom_cle, effet_brut, description, ordre, origine, source_ref, remarque) VALUES ('ressources/familiers#familier:gros:grand-corbeau-sombre', 'gros', 'Grand corbeau sombre', 'grand-corbeau-sombre', NULL, 'Le grand corbeau sombre est une imposante créature ailée dont les plumes noires semblent virer au violet selon l''angle de vue. Relié à la magie de l’Ombre, il possède un sens tactique remarquable et une tendance naturelle à chercher les points faibles. Son regard donne souvent l’impression qu’il comprend davantage qu’il ne devrait.', 5, 'craft', 'Ressources et Craft › Familiers › U32:AM36', NULL);
INSERT INTO familier (id, categorie, nom, nom_cle, effet_brut, description, ordre, origine, source_ref, remarque) VALUES ('ressources/familiers#familier:gros:grand-hibou-rose', 'gros', 'Grand hibou rose', 'grand-hibou-rose', NULL, 'Le grand hibou rose possède un plumage aux teintes rosées et violacées parcouru de légères lueurs magiques. Relié aux pouvoirs de l’Espace/Temps, il semble parfois apparaître légèrement décalé de la réalité. Son comportement calme et mystérieux lui donne une aura étrange pour ceux qui ne sont pas de la bonne magie.', 6, 'craft', 'Ressources et Craft › Familiers › U37:AM41', NULL);
INSERT INTO familier (id, categorie, nom, nom_cle, effet_brut, description, ordre, origine, source_ref, remarque) VALUES ('ressources/familiers#familier:gros:grenouille-geante', 'gros', 'Grenouille géante', 'grenouille-geante', NULL, 'La grenouille géante est un amphibien massif à la peau humide et aux couleurs saphir. Reliée à l’élément de l’Eau, elle possède une grande endurance et se montre étonnamment paisible en dehors des combats. Il peut sembler pataud mais il est plus habile qu''on pourrait le croire, il est également capable d''invoquer naturellement la pluie.', 7, 'craft', 'Ressources et Craft › Familiers › U42:AM46', NULL);
INSERT INTO familier (id, categorie, nom, nom_cle, effet_brut, description, ordre, origine, source_ref, remarque) VALUES ('ressources/familiers#familier:gros:guepard-fulgurant', 'gros', 'Guépard fulgurant', 'guepard-fulgurant', NULL, 'Le guépard fulgurant est un grand félin au pelage parcouru de fines marques lumineuses rappelant des éclairs. Relié à la Foudre, il est connu pour sa vitesse exceptionnelle et ses mouvements brusques presque impossibles à anticiper. Il possède un tempérament énergique et difficile à contenir.', 8, 'craft', 'Ressources et Craft › Familiers › U47:AM51', NULL);
INSERT INTO familier (id, categorie, nom, nom_cle, effet_brut, description, ordre, origine, source_ref, remarque) VALUES ('ressources/familiers#familier:gros:karn', 'gros', 'Karn', 'karn', NULL, 'Le Karn est un quadrupède massif au corps trapu et compact, culminant à environ 1,30 mètre au garrot. Son crâne large est encadré par deux paires de cornes spiralées, épaisses et robustes, capables de briser bois et os lors d’une charge. Sa laine, dense sans être excessivement touffue, possède une particularité remarquable : elle adapte naturellement sa teinte à la magie dominante de la région où il évolue.', 10, 'craft', 'Ressources et Craft › Familiers › U57:AM61', NULL);
INSERT INTO familier (id, categorie, nom, nom_cle, effet_brut, description, ordre, origine, source_ref, remarque) VALUES ('ressources/familiers#familier:gros:loup-arctique', 'gros', 'Loup arctique', 'loup-arctique', NULL, 'Le loup arctique est un grand prédateur au pelage blanc épais, aux détails cyan et aux yeux froids comme la glace. Relié à la magie de la Glace, il dégage une légère fraîcheur permanente autour de lui. Protecteur envers ceux qu’il considère comme sa meute, il est réputé pour sa loyauté.', 9, 'craft', 'Ressources et Craft › Familiers › U52:AM56', NULL);
INSERT INTO familier (id, categorie, nom, nom_cle, effet_brut, description, ordre, origine, source_ref, remarque) VALUES ('ressources/familiers#familier:gros:meduse-blanche', 'gros', 'Méduse blanche', 'meduse-blanche', NULL, 'La méduse blanche est une étrange créature flottante dont le corps translucide semble se déformer lorsqu’on l’observe trop longtemps. Reliée au Vide, elle se flotte silencieusement. Son comportement reste difficile à comprendre pour ceux qui n''ont pas la bonne magie.', 11, 'craft', 'Ressources et Craft › Familiers › U62:AM66', NULL);
INSERT INTO familier (id, categorie, nom, nom_cle, effet_brut, description, ordre, origine, source_ref, remarque) VALUES ('ressources/familiers#familier:gros:potimen-beige', 'gros', 'Potimen beige', 'potimen-beige', NULL, 'Le Potimen beige est un cas particulier chez les potimens, il est celui qui se lie pas à un champ mais à un maître. Relié à la Lumière, il fait partie des rares familiers capables de manier des armes. Malgré son apparence inquiétante, il affiche généralement une attitude calme et protectrice.', 12, 'craft', 'Ressources et Craft › Familiers › U67:AM71', NULL);
INSERT INTO familier (id, categorie, nom, nom_cle, effet_brut, description, ordre, origine, source_ref, remarque) VALUES ('ressources/familiers#familier:gros:rat-vert', 'gros', 'Rat vert', 'rat-vert', NULL, 'Le rat vert est un rongeur massif au pelage terne parcouru de faibles traces vert foncé. Relié à la Nécromancie, il possède une résistance surprenante et une capacité naturelle à empoisonner par la magie ou ses armes ses ennemis. Il se montre particulièrement rusé et adaptable.', 13, 'craft', 'Ressources et Craft › Familiers › U72:AM76', NULL);
INSERT INTO familier (id, categorie, nom, nom_cle, effet_brut, description, ordre, origine, source_ref, remarque) VALUES ('ressources/familiers#familier:gros:sanglier-tellurique', 'gros', 'Sanglier tellurique', 'sanglier-tellurique', NULL, 'Le sanglier tellurique est une imposante créature atteignant près de 2,5 mètres de longueur, recouverte d’une peau épaisse et de plaques rocheuses naturelles et de végétaux. Relié à la magie de la Terre, en plus d''avoir une force brute impressionnante, il est capable d''utiliser certains sorts de la terre.', 14, 'craft', 'Ressources et Craft › Familiers › U77:AM81', NULL);
INSERT INTO familier (id, categorie, nom, nom_cle, effet_brut, description, ordre, origine, source_ref, remarque) VALUES ('ressources/familiers#familier:gros:scorpion-rouge', 'gros', 'Scorpion rouge', 'scorpion-rouge', NULL, 'Le scorpion rouge est un gigantesque arthropode à la carapace rouge parcourue de fines fissures de rouge plus clair. Relié à la magie du Feu, il dégage une chaleur constante et laisse parfois apparaître de petites braises sous ses pattes. Son comportement est agressif face aux menaces mais discipliné envers son propriétaire.', 15, 'craft', 'Ressources et Craft › Familiers › U82:AM86', NULL);
INSERT INTO familier (id, categorie, nom, nom_cle, effet_brut, description, ordre, origine, source_ref, remarque) VALUES ('ressources/familiers#familier:monture:cheval', 'monture', 'Cheval', 'cheval', NULL, 'La monture typique des grands chevaliers et cavaliers des plaines notamment à Erisia, ce puissant animal quadrupède est capable de supporter énormément de poids.', 1, 'craft', 'Ressources et Craft › Familiers › AO12:BG16', NULL);
INSERT INTO familier (id, categorie, nom, nom_cle, effet_brut, description, ordre, origine, source_ref, remarque) VALUES ('ressources/familiers#familier:monture:renne', 'monture', 'Renne', 'renne', NULL, 'Un tracteur typique des régions froides d''Enohr, très endurant et adapté des terrains de neige, il peut tirer un traineau avec 2 personnes et leur équipement.', 2, 'craft', 'Ressources et Craft › Familiers › AO17:BG21', NULL);
INSERT INTO familier (id, categorie, nom, nom_cle, effet_brut, description, ordre, origine, source_ref, remarque) VALUES ('ressources/familiers#familier:monture:sanguiptere', 'monture', 'Sanguiptère', 'sanguiptere', NULL, 'Le Sanguiptère est un coléoptère de grande taille, issu de la convergence entre la magie du vent et du sang, sélectionné et domestiqué pour devenir une monture aérienne de transport.
INSERT INTO familier (id, categorie, nom, nom_cle, effet_brut, description, ordre, origine, source_ref, remarque) VALUES ('ressources/familiers#familier:petit:amphilactrus', 'petit', 'Amphilactrus', 'amphilactrus', '- +1 Vitesse nage', 'L’Amphilactrus est un hybride aquatique qui rappelle beaucoup un mélange entre amphibien et reptile, relié aux magies de Foudre et Eau. Doté d’un corps souple, d’épines dorsales mobiles et d’une peau luisante, il excelle dans la nage.', 1, 'craft', 'Ressources et Craft › Familiers › A12:S16', NULL);
INSERT INTO familier (id, categorie, nom, nom_cle, effet_brut, description, ordre, origine, source_ref, remarque) VALUES ('ressources/familiers#familier:petit:araignee', 'petit', 'Araignée', 'araignee', '- +5% Bonus à l''artisanat', 'Une araignée agile aux mouvements précis et silencieux. Elle tisse de fines toiles avec une patience remarquable.', 2, 'craft', 'Ressources et Craft › Familiers › A17:S21', NULL);
INSERT INTO familier (id, categorie, nom, nom_cle, effet_brut, description, ordre, origine, source_ref, remarque) VALUES ('ressources/familiers#familier:petit:basride', 'petit', 'Basride', 'basride', '- Évolue lentement selon la magie de son maître et deviendra un gros familier', 'Il tient plus de l''animal de compagnie que du compagnon de route adapté au combat. Ils naissent dans les milieux urbains là où les conditions climatiques sont tempérées et douces. Ce sont de vraies boules de poil, incapables de blesser qui que ce soit.', 3, 'craft', 'Ressources et Craft › Familiers › A22:S26', NULL);
INSERT INTO familier (id, categorie, nom, nom_cle, effet_brut, description, ordre, origine, source_ref, remarque) VALUES ('ressources/familiers#familier:petit:blewog', 'petit', 'Blewog', 'blewog', '- +5% Vie en nature', 'Une petite créature ronde pleine de fourrure avec une longue queue qui fait vaguement penser à une plume. Ces petits frugivores sont des proies faciles pour les prédateurs mais ils se reproduisent beaucoup.', 4, 'craft', 'Ressources et Craft › Familiers › A27:S31', NULL);
INSERT INTO familier (id, categorie, nom, nom_cle, effet_brut, description, ordre, origine, source_ref, remarque) VALUES ('ressources/familiers#familier:petit:blobi', 'petit', 'Blobi', 'blobi', '- Donne une gelée de sa couleur tous les 3 jours.', 'Une petite créature gélatineuse prenant différentes couleurs selon sa variété. Curieux et affectueux, il aime suivre son propriétaire en rebondissant derrière lui ou sur lui.', 5, 'craft', 'Ressources et Craft › Familiers › A32:S36', NULL);
INSERT INTO familier (id, categorie, nom, nom_cle, effet_brut, description, ordre, origine, source_ref, remarque) VALUES ('ressources/familiers#familier:petit:boisilag', 'petit', 'Boisilag', 'boisilag', '- Les soins de la terre redonnent +2 santé.', 'La version terre du cornilag, un lapin cornu avec une fourrure brune, la fourrure au cou qui rappelle un buisson et une corne en forme de bois. Il est très curieux et pacifiste.', 6, 'craft', 'Ressources et Craft › Familiers › A37:S41', NULL);
INSERT INTO familier (id, categorie, nom, nom_cle, effet_brut, description, ordre, origine, source_ref, remarque) VALUES ('ressources/familiers#familier:petit:cameleon', 'petit', 'Caméléon', 'cameleon', '- Impose un malus de 5% à ceux qui veulent repérer le maître', 'Un petit reptile calme dont la peau change légèrement selon son environnement.', 7, 'craft', 'Ressources et Craft › Familiers › A42:S46', NULL);
INSERT INTO familier (id, categorie, nom, nom_cle, effet_brut, description, ordre, origine, source_ref, remarque) VALUES ('ressources/familiers#familier:petit:champimousse', 'petit', 'Champimousse', 'champimousse', '- Donne un champignon de sa couleur tous les 3 jours.', 'Une petite créature végétale semi-intelligente couverte de mousse et de champignons, un plus gros peut pousser sur son corps et est récoltable. Il en existe plein de variétés, une par magie.', 8, 'craft', 'Ressources et Craft › Familiers › A47:S51', NULL);
INSERT INTO familier (id, categorie, nom, nom_cle, effet_brut, description, ordre, origine, source_ref, remarque) VALUES ('ressources/familiers#familier:petit:chaperon', 'petit', 'Chaperon', 'chaperon', '- +1 âme récupérée par tour', 'Un petit fantôme de 50cm de la nécromancie sous une cape avec une canne à clochette, rappelant la faucheuse mais miniature. Il reste attaché à son maître et se pose souvent sur sa tête comme s''il était une vraie capuche pour son maître.', 9, 'craft', 'Ressources et Craft › Familiers › A52:S56', NULL);
INSERT INTO familier (id, categorie, nom, nom_cle, effet_brut, description, ordre, origine, source_ref, remarque) VALUES ('ressources/familiers#familier:petit:chat', 'petit', 'Chat', 'chat', '- +2 INI', 'Un félin de petite taille au comportement indépendant et joueur. Tantôt affectueux, tantôt distant, il agit souvent selon ses propres envies.', 10, 'craft', 'Ressources et Craft › Familiers › A57:S61', NULL);
INSERT INTO familier (id, categorie, nom, nom_cle, effet_brut, description, ordre, origine, source_ref, remarque) VALUES ('ressources/familiers#familier:petit:chauve-souris-mauve', 'petit', 'Chauve-souris mauve', 'chauve-souris-mauve', '- Pas de désavantage au jet de perception dû à l''obscurité', 'Un petit mammifère volant nocturne utilisant des ultrasons pour se repérer dans l’obscurité. Son affinité avec la magie de l''ombre fait que son maître a une meilleure vue dans l''obscurité.', 11, 'craft', 'Ressources et Craft › Familiers › A62:S66', NULL);
INSERT INTO familier (id, categorie, nom, nom_cle, effet_brut, description, ordre, origine, source_ref, remarque) VALUES ('ressources/familiers#familier:petit:chien', 'petit', 'Chien', 'chien', '- +5% Survie', 'Une créature loyale et sociable qui développe rapidement un lien fort avec son propriétaire. Toujours attentif, il accompagne naturellement les déplacements de son maître.', 12, 'craft', 'Ressources et Craft › Familiers › A67:S71', NULL);
INSERT INTO familier (id, categorie, nom, nom_cle, effet_brut, description, ordre, origine, source_ref, remarque) VALUES ('ressources/familiers#familier:petit:chouette', 'petit', 'Chouette', 'chouette', '- +5% Observation', 'Un petit oiseau nocturne au regard vif et aux mouvements silencieux. Elle observe constamment son environnement et semble remarquer des détails que d’autres ignorent.', 13, 'craft', 'Ressources et Craft › Familiers › A72:S76', NULL);
INSERT INTO familier (id, categorie, nom, nom_cle, effet_brut, description, ordre, origine, source_ref, remarque) VALUES ('ressources/familiers#familier:petit:corbeau', 'petit', 'Corbeau', 'corbeau', '- Récupère tous les 3 jours un petit objet comme une pièce d''or.', 'Un oiseau noir intelligent au regard perçant. Curieux de nature, il aime observer les personnes et récupérer divers petits objets.', 14, 'craft', 'Ressources et Craft › Familiers › A77:S81', NULL);
INSERT INTO familier (id, categorie, nom, nom_cle, effet_brut, description, ordre, origine, source_ref, remarque) VALUES ('ressources/familiers#familier:petit:faucon', 'petit', 'Faucon', 'faucon', '- Réduit de 5% le malus pour viser une partie du corps', 'Un oiseau de proie élégant aux yeux particulièrement aiguisés. Il reste calme et attentif avant de réagir avec une vitesse surprenante.', 15, 'craft', 'Ressources et Craft › Familiers › A82:S86', NULL);
INSERT INTO familier (id, categorie, nom, nom_cle, effet_brut, description, ordre, origine, source_ref, remarque) VALUES ('ressources/familiers#familier:petit:feu-follet', 'petit', 'Feu-follet', 'feu-follet', '- Éclaire autant qu''une lanterne', 'Une petite sphère lumineuse flottante animée par une étrange énergie magique. Sa couleur varie selon la/les magie(s) de son maître.', 16, 'craft', 'Ressources et Craft › Familiers › A87:S91', NULL);
INSERT INTO familier (id, categorie, nom, nom_cle, effet_brut, description, ordre, origine, source_ref, remarque) VALUES ('ressources/familiers#familier:petit:flamilag', 'petit', 'Flamilag', 'flamilag', '- La météo "canicule" dure 2 tours de plus', 'La version feu du cornilag, un lapin cornu avec une fourrure rouge, la fourrure plus épaisse au cou qui rappelle une flamme et une corne brûlante. Il a un sale caractère.', 17, 'craft', 'Ressources et Craft › Familiers › A92:S96', NULL);
INSERT INTO familier (id, categorie, nom, nom_cle, effet_brut, description, ordre, origine, source_ref, remarque) VALUES ('ressources/familiers#familier:petit:fulgilag', 'petit', 'Fulgilag', 'fulgilag', '- +1 Vitesse pour le sprint au sol', 'La version foudre du cornilag, un lapin cornu avec une fourrure brun clair, la fourrure au cou couleur jaune et une corne rappelant un éclair. Il est vif et craintif.', 18, 'craft', 'Ressources et Craft › Familiers › A97:S101', NULL);
INSERT INTO familier (id, categorie, nom, nom_cle, effet_brut, description, ordre, origine, source_ref, remarque) VALUES ('ressources/familiers#familier:petit:gecko-gris', 'petit', 'Gecko gris', 'gecko-gris', '- Les météos durent 1 tour de plus quand elles sont lancées.
INSERT INTO familier (id, categorie, nom, nom_cle, effet_brut, description, ordre, origine, source_ref, remarque) VALUES ('ressources/familiers#familier:petit:herisson-brun', 'petit', 'Hérisson brun', 'herisson-brun', '- +1AP de base', 'La version miniature du hérisson tectonique. Bien qu’assez timide, il se montre étonnamment robuste malgré sa taille.', 20, 'craft', 'Ressources et Craft › Familiers › A107:S111', NULL);
INSERT INTO familier (id, categorie, nom, nom_cle, effet_brut, description, ordre, origine, source_ref, remarque) VALUES ('ressources/familiers#familier:petit:hibou', 'petit', 'Hibou', 'hibou', '- +5% Connaissance', 'Un oiseau nocturne au plumage épais et au regard profond. Discret et posé, il demeure attentif à ce qui l’entoure même dans l’obscurité la plus totale.', 21, 'craft', 'Ressources et Craft › Familiers › A112:S116', NULL);
INSERT INTO familier (id, categorie, nom, nom_cle, effet_brut, description, ordre, origine, source_ref, remarque) VALUES ('ressources/familiers#familier:petit:luciombre', 'petit', 'Luciombre', 'luciombre', '- +1% critique à tous jets qui impliquent la Perception', 'Un insecte de la même famille que les lucioles, sauf qu''il est entouré d''un nuage sombre, seuls ses yeux et son abdomen percent ce voile de ténèbres et lui donnent une apparence effrayante.', 22, 'craft', 'Ressources et Craft › Familiers › A117:S121', NULL);
INSERT INTO familier (id, categorie, nom, nom_cle, effet_brut, description, ordre, origine, source_ref, remarque) VALUES ('ressources/familiers#familier:petit:metali', 'petit', 'Métali', 'metali', '- Donne un minerai de sa nature tous les 3 jours.', 'Une petite créature gélatineuse faite de métal fondu dont l''origine peut varier. Curieux et affectueux, il aime suivre son propriétaire en rebondissant derrière lui ou sur lui.', 23, 'craft', 'Ressources et Craft › Familiers › A122:S126', NULL);
INSERT INTO familier (id, categorie, nom, nom_cle, effet_brut, description, ordre, origine, source_ref, remarque) VALUES ('ressources/familiers#familier:petit:mini-drake', 'petit', 'Mini-drake', 'mini-drake', '- +1 dégât avec les armes', 'Une petite créature qui rappelle les drakes mais elle n''est rien qu''un reptile à écailles épaisses qui mime ces derniers et qui pense faire peur. Il aime se poser sur des trésors. Ses écailles changent selon la magie du maître.', 25, 'craft', 'Ressources et Craft › Familiers › A132:S136', NULL);
INSERT INTO familier (id, categorie, nom, nom_cle, effet_brut, description, ordre, origine, source_ref, remarque) VALUES ('ressources/familiers#familier:petit:mini-hydrix', 'petit', 'Mini-hydrix', 'mini-hydrix', '- Augmente la résistance à la confusion', 'Un oiseau ressemblant à un hydrix laissant parfois tomber quelques quelques gouttes d''eau. Il aime être sur la tête de son maître.', 26, 'craft', 'Ressources et Craft › Familiers › A137:S141', NULL);
INSERT INTO familier (id, categorie, nom, nom_cle, effet_brut, description, ordre, origine, source_ref, remarque) VALUES ('ressources/familiers#familier:petit:mini-phenix', 'petit', 'Mini-phénix', 'mini-phenix', '- Augmente la résistance à la brûlure', 'Un oiseau ressemblant à un phénix laissant parfois tomber quelques braises inoffensives. Il aime être sur l''épaule de son maître.', 27, 'craft', 'Ressources et Craft › Familiers › A142:S146', NULL);
INSERT INTO familier (id, categorie, nom, nom_cle, effet_brut, description, ordre, origine, source_ref, remarque) VALUES ('ressources/familiers#familier:petit:minitaire', 'petit', 'Minitaire', 'minitaire', '- +2 aux dégâts magiques selon sa magie.', 'Une version miniature d’un élémentaire, conservant une faible portion du pouvoir de son élément d’origine. Malgré sa petite taille, son énergie magique reste clairement perceptible.', 24, 'craft', 'Ressources et Craft › Familiers › A127:S131', NULL);
INSERT INTO familier (id, categorie, nom, nom_cle, effet_brut, description, ordre, origine, source_ref, remarque) VALUES ('ressources/familiers#familier:petit:momilag', 'petit', 'Momilag', 'momilag', '- La fatigue niveau 1 ne donne réduit plus les dégâts', 'La version espace/temps du cornilag, un lapin cornu avec une fourrure un peu rose, il possède des bandages de momie couleur grise ainsi qu''une corne parfaitement rose. Il est assez mystérieux et semble voir plus de choses que les autres.', 28, 'craft', 'Ressources et Craft › Familiers › A147:S151', NULL);
INSERT INTO familier (id, categorie, nom, nom_cle, effet_brut, description, ordre, origine, source_ref, remarque) VALUES ('ressources/familiers#familier:petit:perroquet', 'petit', 'Perroquet', 'perroquet', '- +5% Diplomatie', 'Un oiseau coloré et bruyant doté d’une grande intelligence. Il adore reproduire des sons, des mots et parfois des phrases entendues autour de lui.', 29, 'craft', 'Ressources et Craft › Familiers › A152:S156', NULL);
INSERT INTO familier (id, categorie, nom, nom_cle, effet_brut, description, ordre, origine, source_ref, remarque) VALUES ('ressources/familiers#familier:petit:poule', 'petit', 'Poule', 'poule', '- Pond un oeuf tous les 3 jours', 'Un oiseau domestique à l’attitude parfois maladroite mais étonnamment débrouillarde. Elle passe la majorité de son temps à picorer et explorer son environnement.', 30, 'craft', 'Ressources et Craft › Familiers › A157:S161', NULL);
INSERT INTO familier (id, categorie, nom, nom_cle, effet_brut, description, ordre, origine, source_ref, remarque) VALUES ('ressources/familiers#familier:petit:putrilag', 'petit', 'Putrilag', 'putrilag', '- Les sorts de nécromancie coutent 1 âme de moins.', 'La version nécromancie du cornilag, un lapin cornu avec une fourrure verte, sa corne et est parfaitement blanche mais possède une apparence plus qu''effrayante. On sait que ses petits naissance via des cadavres de d''autre cornilag.', 31, 'craft', 'Ressources et Craft › Familiers › A162:S166', NULL);
INSERT INTO familier (id, categorie, nom, nom_cle, effet_brut, description, ordre, origine, source_ref, remarque) VALUES ('ressources/familiers#familier:petit:renard', 'petit', 'Renard', 'renard', '- +5% Réflexe', 'Un petit canidé au pelage doux et à la queue touffue. Curieux et malin, il aime explorer discrètement son environnement.', 32, 'craft', 'Ressources et Craft › Familiers › A167:S171', NULL);
INSERT INTO familier (id, categorie, nom, nom_cle, effet_brut, description, ordre, origine, source_ref, remarque) VALUES ('ressources/familiers#familier:petit:rongeur', 'petit', 'Rongeur', 'rongeur', '- +5% Ruse', 'Une petite créature vive et énergique aux mouvements rapides. Toujours occupé à fouiller ou transporter quelque chose, il semble incapable de rester immobile.', 33, 'craft', 'Ressources et Craft › Familiers › A172:S176', NULL);
INSERT INTO familier (id, categorie, nom, nom_cle, effet_brut, description, ordre, origine, source_ref, remarque) VALUES ('ressources/familiers#familier:petit:salamandre', 'petit', 'Salamandre', 'salamandre', '- +5% Vigueur', 'Un petit lézard aux couleurs éclatantes dont le corps dégage une légère chaleur. Curieuse et paisible, elle aime se reposer près des sources de chaleur.', 34, 'craft', 'Ressources et Craft › Familiers › A177:S181', NULL);
INSERT INTO familier (id, categorie, nom, nom_cle, effet_brut, description, ordre, origine, source_ref, remarque) VALUES ('ressources/familiers#familier:petit:sangilag', 'petit', 'Sangilag', 'sangilag', '- Les sorts de sang coutent 1 sang de moins.', 'La version sang du cornilag, un lapin cornu avec une fourrure bordeaux, sa corne est de la même couleur et possède 3 paires de pattes. C''est le plus gros représentant des cornilag et atteint facilement les 20 kilos.', 35, 'craft', 'Ressources et Craft › Familiers › A182:S186', NULL);
INSERT INTO familier (id, categorie, nom, nom_cle, effet_brut, description, ordre, origine, source_ref, remarque) VALUES ('ressources/familiers#familier:petit:serpent', 'petit', 'Serpent', 'serpent', '- +5% Distinction', 'Un reptile silencieux aux mouvements fluides et précis. Calme et patient, il observe longuement son environnement avant d’agir au moment opportun.', 36, 'craft', 'Ressources et Craft › Familiers › A187:S191', NULL);
